function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sb($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>45]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$h=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ['ok'=>$h>=200&&$h<300,'data'=>is_array($d)?$d:[]];}
$rows=sb('GET','jessica_memory?select=*&order=importance.desc,created_at.desc&limit=500')['data'];
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jessica Memory</title><style>body{margin:0;background:#f5f3ef;font-family:Arial;color:#111}.hero{background:#111827;color:white;padding:30px}.hero h1{color:#c8a96e}.wrap{padding:20px;max-width:1600px;margin:auto}.panel{background:white;border-radius:16px;overflow:hidden}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}th{background:#faf9f6;font-size:11px;color:#777;text-transform:uppercase}</style></head><body><div class="hero"><h1>Jessica Memory</h1><p>Conversation memory, decisions, corrections, preferences, and strategy notes.</p></div><main class="wrap"><section class="panel"><table><tr><th>Importance</th><th>Category</th><th>Question / Title</th><th>Response / Notes</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['importance'])?></td><td><?=h($r['category'])?><br><?=h($r['memory_type'])?></td><td><strong><?=h($r['title'])?></strong><br><?=h($r['question'])?></td><td><?=nl2br(h($r['response']))?><br><small><?=h($r['notes'])?></small></td><td><?=h($r['created_at'])?></td></tr><?php endforeach;?></table></section></main></body></html>